# 10-ingilizce-15 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 800 320" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="800" height="320" rx="16" fill="#f8fafc" stroke="#cbd5e1" stroke-width="2"/><rect x="16" y="14" width="768" height="40" rx="10" fill="#1e293b"/><text x="400" y="40" text-anchor="middle" font-size="16" font-weight="700" fill="#ffffff">Past Continuous Tense: was / were + V-ing</text><line x1="50" y1="120" x2="740" y2="120" stroke="#334155" stroke-width="3"/><polygon points="752,120 738,112 738,128" fill="#334155"/><text x="50" y="152" font-size="12" fill="#475569">PAST (Geçmiş)</text><text x="705" y="152" text-anchor="middle" font-size="12" fill="#475569">NOW (Şimdi)</text><rect x="200" y="98" width="340" height="44" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/><text x="370" y="125" text-anchor="middle" font-size="13" font-weight="700" fill="#1e3a8a">We were driving to Cappadocia.</text><line x1="370" y1="66" x2="370" y2="164" stroke="#dc2626" stroke-width="2" stroke-dasharray="5 4"/><circle cx="370" cy="120" r="5" fill="#dc2626"/><text x="370" y="180" text-anchor="middle" font-size="12" font-weight="700" fill="#b91c1c">at 8 p.m. yesterday (eylem o anda sürüyordu)</text><rect x="30" y="195" width="235" height="108" rx="12" fill="#eff6ff" stroke="#1d4ed8" stroke-width="2"/><rect x="30" y="195" width="235" height="28" rx="10" fill="#1d4ed8"/><text x="148" y="214" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">Affirmative (+)</text><text x="148" y="245" text-anchor="middle" font-size="12" fill="#1e293b">I / He / She / It + was + V-ing</text><text x="148" y="267" text-anchor="middle" font-size="12" fill="#1e293b">You / We / They + were + V-ing</text><text x="148" y="289" text-anchor="middle" font-size="12" font-style="italic" fill="#1d4ed8">They were sightseeing.</text><rect x="282" y="195" width="235" height="108" rx="12" fill="#ecfdf5" stroke="#047857" stroke-width="2"/><rect x="282" y="195" width="235" height="28" rx="10" fill="#047857"/><text x="400" y="214" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">Negative (−)</text><text x="400" y="245" text-anchor="middle" font-size="12" fill="#1e293b">was not (wasn\'t) + V-ing</text><text x="400" y="267" text-anchor="middle" font-size="12" fill="#1e293b">were not (weren\'t) + V-ing</text><text x="400" y="289" text-anchor="middle" font-size="12" font-style="italic" fill="#047857">She wasn\'t sleeping on the bus.</text><rect x="535" y="195" width="235" height="108" rx="12" fill="#fffbeb" stroke="#b45309" stroke-width="2"/><rect x="535" y="195" width="235" height="28" rx="10" fill="#b45309"/><text x="652" y="214" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">Question (?)</text><text x="652" y="245" text-anchor="middle" font-size="12" fill="#1e293b">Was / Were + subject + V-ing?</text><text x="652" y="267" text-anchor="middle" font-size="12" fill="#1e293b">Were you taking photos?</text><text x="652" y="289" text-anchor="middle" font-size="12" font-style="italic" fill="#b45309">Yes, I was. / No, I wasn\'t.</text></svg>', 'b2': '<svg viewBox="0 0 800 320" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="800" height="320" rx="16" fill="#f8fafc" stroke="#cbd5e1" stroke-width="2"/><rect x="16" y="14" width="768" height="40" rx="10" fill="#1e293b"/><text x="400" y="40" text-anchor="middle" font-size="16" font-weight="700" fill="#ffffff">When vs. While: Interrupted and Parallel Actions</text><rect x="30" y="68" width="360" height="192" rx="12" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/><rect x="30" y="68" width="360" height="30" rx="10" fill="#2563eb"/><text x="210" y="88" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">Interrupted Action (Kesilen Eylem)</text><rect x="50" y="128" width="320" height="32" rx="8" fill="#bfdbfe" stroke="#1d4ed8" stroke-width="1.5"/><text x="150" y="149" text-anchor="middle" font-size="12" fill="#1e3a8a">I was waiting at the gate</text><polygon points="292,108 280,140 292,140 282,178 310,132 297,132 306,108" fill="#dc2626"/><text x="210" y="198" text-anchor="middle" font-size="12" font-weight="700" fill="#b91c1c">... when the announcement came.</text><text x="210" y="222" text-anchor="middle" font-size="12" fill="#1e293b">Long action: Past Continuous (uzun eylem)</text><text x="210" y="244" text-anchor="middle" font-size="12" fill="#1e293b">Short action: when + Simple Past (kısa eylem)</text><rect x="410" y="68" width="360" height="192" rx="12" fill="#ecfdf5" stroke="#059669" stroke-width="2"/><rect x="410" y="68" width="360" height="30" rx="10" fill="#059669"/><text x="590" y="88" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">Parallel Actions (Eş Zamanlı Eylemler)</text><rect x="430" y="116" width="320" height="30" rx="8" fill="#bbf7d0" stroke="#047857" stroke-width="1.5"/><text x="590" y="136" text-anchor="middle" font-size="12" fill="#064e3b">While my dad was driving,</text><rect x="430" y="156" width="320" height="30" rx="8" fill="#bbf7d0" stroke="#047857" stroke-width="1.5"/><text x="590" y="176" text-anchor="middle" font-size="12" fill="#064e3b">my mom was reading the map.</text><text x="590" y="218" text-anchor="middle" font-size="12" fill="#1e293b">While + Past Continuous, Past Continuous</text><text x="590" y="240" text-anchor="middle" font-size="12" fill="#1e293b">İki eylem aynı anda sürüyordu.</text><rect x="30" y="272" width="740" height="34" rx="8" fill="#e2e8f0"/><text x="400" y="294" text-anchor="middle" font-size="13" font-weight="600" fill="#0f172a">While I was sleeping, the train stopped. = The train stopped while I was sleeping.</text></svg>', 'b3': '<svg viewBox="0 0 800 320" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="800" height="320" rx="16" fill="#f8fafc" stroke="#cbd5e1" stroke-width="2"/><rect x="16" y="14" width="768" height="40" rx="10" fill="#1e293b"/><text x="400" y="40" text-anchor="middle" font-size="16" font-weight="700" fill="#ffffff">Sequencing Words: Telling a Travel Story in Order</text><rect x="30" y="76" width="130" height="124" rx="12" fill="#eff6ff" stroke="#1d4ed8" stroke-width="2"/><rect x="30" y="76" width="130" height="30" rx="10" fill="#1d4ed8"/><text x="95" y="96" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">1. First</text><text x="95" y="132" text-anchor="middle" font-size="11" fill="#1e293b">First, we packed</text><text x="95" y="150" text-anchor="middle" font-size="11" fill="#1e293b">our suitcases.</text><text x="95" y="182" text-anchor="middle" font-size="11" font-style="italic" fill="#1d4ed8">(İlk olarak)</text><line x1="162" y1="138" x2="174" y2="138" stroke="#475569" stroke-width="3"/><polygon points="181,138 173,133 173,143" fill="#475569"/><rect x="182" y="76" width="130" height="124" rx="12" fill="#ecfdf5" stroke="#047857" stroke-width="2"/><rect x="182" y="76" width="130" height="30" rx="10" fill="#047857"/><text x="247" y="96" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">2. Then</text><text x="247" y="132" text-anchor="middle" font-size="11" fill="#1e293b">Then, we caught</text><text x="247" y="150" text-anchor="middle" font-size="11" fill="#1e293b">the early bus.</text><text x="247" y="182" text-anchor="middle" font-size="11" font-style="italic" fill="#047857">(Sonra)</text><line x1="314" y1="138" x2="326" y2="138" stroke="#475569" stroke-width="3"/><polygon points="333,138 325,133 325,143" fill="#475569"/><rect x="334" y="76" width="130" height="124" rx="12" fill="#fffbeb" stroke="#b45309" stroke-width="2"/><rect x="334" y="76" width="130" height="30" rx="10" fill="#b45309"/><text x="399" y="96" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">3. After that</text><text x="399" y="132" text-anchor="middle" font-size="11" fill="#1e293b">After that, we</text><text x="399" y="150" text-anchor="middle" font-size="11" fill="#1e293b">visited a museum.</text><text x="399" y="182" text-anchor="middle" font-size="11" font-style="italic" fill="#b45309">(Ondan sonra)</text><line x1="466" y1="138" x2="478" y2="138" stroke="#475569" stroke-width="3"/><polygon points="485,138 477,133 477,143" fill="#475569"/><rect x="486" y="76" width="130" height="124" rx="12" fill="#f5f3ff" stroke="#6d28d9" stroke-width="2"/><rect x="486" y="76" width="130" height="30" rx="10" fill="#6d28d9"/><text x="551" y="96" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">4. Later</text><text x="551" y="132" text-anchor="middle" font-size="11" fill="#1e293b">Later, we had</text><text x="551" y="150" text-anchor="middle" font-size="11" fill="#1e293b">dinner by the sea.</text><text x="551" y="182" text-anchor="middle" font-size="11" font-style="italic" fill="#6d28d9">(Daha sonra)</text><line x1="618" y1="138" x2="630" y2="138" stroke="#475569" stroke-width="3"/><polygon points="637,138 629,133 629,143" fill="#475569"/><rect x="638" y="76" width="130" height="124" rx="12" fill="#fef2f2" stroke="#b91c1c" stroke-width="2"/><rect x="638" y="76" width="130" height="30" rx="10" fill="#b91c1c"/><text x="703" y="96" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">5. Finally</text><text x="703" y="132" text-anchor="middle" font-size="11" fill="#1e293b">Finally, we</text><text x="703" y="150" text-anchor="middle" font-size="11" fill="#1e293b">flew back home.</text><text x="703" y="182" text-anchor="middle" font-size="11" font-style="italic" fill="#b91c1c">(Sonunda)</text><rect x="30" y="218" width="738" height="86" rx="12" fill="#fef3c7" stroke="#d97706" stroke-width="2"/><text x="399" y="242" text-anchor="middle" font-size="13" font-weight="700" fill="#92400e">More Time Linkers (Diğer Zaman Bağlayıcıları)</text><text x="399" y="266" text-anchor="middle" font-size="12" fill="#1e293b">as soon as (-ır -maz)   |   meanwhile (bu arada)   |   suddenly (aniden)   |   during + noun (... sırasında)</text><text x="399" y="290" text-anchor="middle" font-size="12" font-style="italic" fill="#1e293b">As soon as we arrived at the hotel, we checked in. During the flight, I watched a film.</text></svg>', 'b4': '<svg viewBox="0 0 800 320" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="800" height="320" rx="16" fill="#f8fafc" stroke="#cbd5e1" stroke-width="2"/><rect x="16" y="14" width="768" height="40" rx="10" fill="#1e293b"/><text x="400" y="40" text-anchor="middle" font-size="16" font-weight="700" fill="#ffffff">Describing Destinations: Useful Adjectives</text><rect x="30" y="66" width="360" height="112" rx="12" fill="#ecfdf5" stroke="#047857" stroke-width="2"/><rect x="30" y="66" width="360" height="28" rx="10" fill="#047857"/><text x="210" y="85" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">Positive (Olumlu)</text><text x="120" y="118" text-anchor="middle" font-size="12" fill="#1e293b">breathtaking (nefes kesici)</text><text x="120" y="140" text-anchor="middle" font-size="12" fill="#1e293b">peaceful (huzurlu)</text><text x="120" y="162" text-anchor="middle" font-size="12" fill="#1e293b">historic (tarihî)</text><text x="300" y="118" text-anchor="middle" font-size="12" fill="#1e293b">picturesque (resim gibi)</text><text x="300" y="140" text-anchor="middle" font-size="12" fill="#1e293b">lively (hareketli)</text><text x="300" y="162" text-anchor="middle" font-size="12" fill="#1e293b">unspoilt (bozulmamış)</text><rect x="410" y="66" width="360" height="112" rx="12" fill="#fef2f2" stroke="#b91c1c" stroke-width="2"/><rect x="410" y="66" width="360" height="28" rx="10" fill="#b91c1c"/><text x="590" y="85" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">Negative (Olumsuz)</text><text x="500" y="118" text-anchor="middle" font-size="12" fill="#1e293b">crowded (kalabalık)</text><text x="500" y="140" text-anchor="middle" font-size="12" fill="#1e293b">noisy (gürültülü)</text><text x="500" y="162" text-anchor="middle" font-size="12" fill="#1e293b">polluted (kirli)</text><text x="680" y="118" text-anchor="middle" font-size="12" fill="#1e293b">overpriced (çok pahalı)</text><text x="680" y="140" text-anchor="middle" font-size="12" fill="#1e293b">touristy (aşırı turistik)</text><text x="680" y="162" text-anchor="middle" font-size="12" fill="#1e293b">dull (sıkıcı)</text><rect x="30" y="190" width="360" height="112" rx="12" fill="#eff6ff" stroke="#1d4ed8" stroke-width="2"/><rect x="30" y="190" width="360" height="28" rx="10" fill="#1d4ed8"/><text x="210" y="209" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">Types of Places (Mekân Türleri)</text><text x="210" y="242" text-anchor="middle" font-size="12" fill="#1e293b">coastal town (sahil kasabası)</text><text x="210" y="264" text-anchor="middle" font-size="12" fill="#1e293b">mountain village (dağ köyü)</text><text x="210" y="286" text-anchor="middle" font-size="12" fill="#1e293b">historic city centre (tarihî şehir merkezi)</text><rect x="410" y="190" width="360" height="112" rx="12" fill="#f5f3ff" stroke="#6d28d9" stroke-width="2"/><rect x="410" y="190" width="360" height="28" rx="10" fill="#6d28d9"/><text x="590" y="209" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">Very vs. Absolutely</text><text x="590" y="242" text-anchor="middle" font-size="12" fill="#1e293b">very + normal adj: very beautiful, very big</text><text x="590" y="264" text-anchor="middle" font-size="12" fill="#1e293b">absolutely + strong adj: absolutely stunning</text><text x="590" y="286" text-anchor="middle" font-size="12" font-weight="700" fill="#b91c1c">NOT: very breathtaking / absolutely nice</text></svg>', 'b5': '<svg viewBox="0 0 800 320" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="800" height="320" rx="16" fill="#f8fafc" stroke="#cbd5e1" stroke-width="2"/><rect x="16" y="14" width="768" height="40" rx="10" fill="#1e293b"/><text x="400" y="40" text-anchor="middle" font-size="16" font-weight="700" fill="#ffffff">Travel Problems: Problem → Polite Request → Solution</text><text x="135" y="82" text-anchor="middle" font-size="13" font-weight="700" fill="#b91c1c">Problem (Sorun)</text><text x="415" y="82" text-anchor="middle" font-size="13" font-weight="700" fill="#1d4ed8">Polite Complaint / Request</text><text x="680" y="82" text-anchor="middle" font-size="13" font-weight="700" fill="#047857">Solution (Çözüm)</text><rect x="30" y="95" width="210" height="58" rx="10" fill="#fef2f2" stroke="#b91c1c" stroke-width="2"/><text x="135" y="129" text-anchor="middle" font-size="12" font-weight="700" fill="#7f1d1d">Lost luggage (kayıp bagaj)</text><polygon points="246,124 262,124 262,118 272,124 262,130 262,124" fill="#475569" stroke="#475569" stroke-width="2"/><rect x="275" y="95" width="285" height="58" rx="10" fill="#eff6ff" stroke="#1d4ed8" stroke-width="2"/><text x="417" y="119" text-anchor="middle" font-size="12" fill="#1e293b">Excuse me, my suitcase hasn\'t arrived.</text><text x="417" y="139" text-anchor="middle" font-size="12" fill="#1e293b">Where is the lost luggage office?</text><polygon points="566,124 582,124 582,118 592,124 582,130 582,124" fill="#475569" stroke="#475569" stroke-width="2"/><rect x="595" y="95" width="175" height="58" rx="10" fill="#ecfdf5" stroke="#047857" stroke-width="2"/><text x="682" y="129" text-anchor="middle" font-size="12" fill="#064e3b">Fill in a report form.</text><rect x="30" y="165" width="210" height="58" rx="10" fill="#fef2f2" stroke="#b91c1c" stroke-width="2"/><text x="135" y="199" text-anchor="middle" font-size="12" font-weight="700" fill="#7f1d1d">Delayed flight (rötar)</text><polygon points="246,194 262,194 262,188 272,194 262,200 262,194" fill="#475569" stroke="#475569" stroke-width="2"/><rect x="275" y="165" width="285" height="58" rx="10" fill="#eff6ff" stroke="#1d4ed8" stroke-width="2"/><text x="417" y="189" text-anchor="middle" font-size="12" fill="#1e293b">I\'m sorry to bother you, but how</text><text x="417" y="209" text-anchor="middle" font-size="12" fill="#1e293b">long will the flight be delayed?</text><polygon points="566,194 582,194 582,188 592,194 582,200 582,194" fill="#475569" stroke="#475569" stroke-width="2"/><rect x="595" y="165" width="175" height="58" rx="10" fill="#ecfdf5" stroke="#047857" stroke-width="2"/><text x="682" y="199" text-anchor="middle" font-size="12" fill="#064e3b">Get a meal voucher.</text><rect x="30" y="235" width="210" height="58" rx="10" fill="#fef2f2" stroke="#b91c1c" stroke-width="2"/><text x="135" y="269" text-anchor="middle" font-size="12" font-weight="700" fill="#7f1d1d">Noisy room (gürültülü oda)</text><polygon points="246,264 262,264 262,258 272,264 262,270 262,264" fill="#475569" stroke="#475569" stroke-width="2"/><rect x="275" y="235" width="285" height="58" rx="10" fill="#eff6ff" stroke="#1d4ed8" stroke-width="2"/><text x="417" y="259" text-anchor="middle" font-size="12" fill="#1e293b">I\'m afraid my room is very noisy.</text><text x="417" y="279" text-anchor="middle" font-size="12" fill="#1e293b">Would it be possible to change rooms?</text><polygon points="566,264 582,264 582,258 592,264 582,270 582,264" fill="#475569" stroke="#475569" stroke-width="2"/><rect x="595" y="235" width="175" height="58" rx="10" fill="#ecfdf5" stroke="#047857" stroke-width="2"/><text x="682" y="269" text-anchor="middle" font-size="12" fill="#064e3b">Move to a quieter room.</text></svg>', 'b6': '<svg viewBox="0 0 800 320" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="800" height="320" rx="16" fill="#f8fafc" stroke="#cbd5e1" stroke-width="2"/><rect x="16" y="14" width="768" height="40" rx="10" fill="#1e293b"/><text x="400" y="40" text-anchor="middle" font-size="16" font-weight="700" fill="#ffffff">Structure of a Travel Blog Post and a Postcard</text><rect x="30" y="66" width="470" height="244" rx="12" fill="#ffffff" stroke="#94a3b8" stroke-width="2"/><rect x="42" y="76" width="446" height="36" rx="8" fill="#1d4ed8"/><text x="265" y="99" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">Title: Lost in the Stone Streets of Mardin</text><rect x="42" y="120" width="446" height="56" rx="8" fill="#eff6ff" stroke="#93c5fd" stroke-width="1.5"/><text x="265" y="142" text-anchor="middle" font-size="12" font-weight="700" fill="#1e3a8a">1. Introduction: Where? When? Who with?</text><text x="265" y="163" text-anchor="middle" font-size="12" font-style="italic" fill="#1e293b">Last summer, I went to Mardin with my family.</text><rect x="42" y="182" width="446" height="56" rx="8" fill="#ecfdf5" stroke="#6ee7b7" stroke-width="1.5"/><text x="265" y="204" text-anchor="middle" font-size="12" font-weight="700" fill="#064e3b">2. Body: Events in order, highlights, surprises</text><text x="265" y="225" text-anchor="middle" font-size="12" font-style="italic" fill="#1e293b">We were walking in the old bazaar when suddenly ...</text><rect x="42" y="244" width="446" height="56" rx="8" fill="#fffbeb" stroke="#fcd34d" stroke-width="1.5"/><text x="265" y="266" text-anchor="middle" font-size="12" font-weight="700" fill="#92400e">3. Conclusion: Feelings + Recommendation</text><text x="265" y="287" text-anchor="middle" font-size="12" font-style="italic" fill="#1e293b">It was absolutely amazing. Don\'t miss the sunset!</text><rect x="520" y="66" width="250" height="244" rx="12" fill="#fdf2f8" stroke="#be185d" stroke-width="2" stroke-dasharray="8 4"/><rect x="520" y="66" width="250" height="32" rx="10" fill="#be185d"/><text x="645" y="87" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">Postcard Phrases</text><text x="645" y="124" text-anchor="middle" font-size="12" fill="#1e293b">Dear Ayşe, / Hi Can,</text><text x="645" y="150" text-anchor="middle" font-size="12" fill="#1e293b">Greetings from Antalya!</text><text x="645" y="176" text-anchor="middle" font-size="12" fill="#1e293b">The weather is lovely.</text><text x="645" y="202" text-anchor="middle" font-size="12" fill="#1e293b">We are having a great time.</text><text x="645" y="228" text-anchor="middle" font-size="12" fill="#1e293b">We have already visited Side.</text><text x="645" y="254" text-anchor="middle" font-size="12" font-weight="700" fill="#be185d">Wish you were here!</text><text x="645" y="280" text-anchor="middle" font-size="12" fill="#1e293b">Love, / Best wishes, Zeynep</text></svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
